package main

import (
	"bytes"
	"encoding/json"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"reflect"
	"strconv"
	"testing"
)

// wireContractPath is the payload generated by the daemon-side core test. The
// TUI is a separate module and imports no Beacon package, so it decodes the
// shared file with its own wire structs.
const wireContractPath = "../../docs/wire/loopback.json"

// coreVocabularyPath is the core source that declares the control verbs. The
// TUI imports no Beacon package, so the contract test resolves core's names
// from source instead of importing them.
const coreVocabularyPath = "../../pkg/core/control.go"

type wireContractPayload struct {
	Runs    []Run         `json:"runs"`
	Event   Event         `json:"event"`
	Control ControlResult `json:"control"`
}

// wirePingPayload and wirePRChangedPayload are the data shapes of the two
// non-harness events the events route emits. The harness event shape is pinned
// by the Event field of wireContractPayload.
type wirePingPayload struct {
	Time string `json:"time"`
}

type wirePRChangedPayload struct {
	PR int `json:"pr"`
}

// decodeWireStrict rejects unknown keys. json.Unmarshal silently ignores a
// field the target does not name, so a daemon-side field addition would pass
// this contract unnoticed. The decoder is shared by every fixture below.
func decodeWireStrict(data []byte, dst any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	return dec.Decode(dst)
}

// TestWireContractDecode proves the monitor reads every field the daemon
// emits. If a core wire tag is renamed, the core test regenerates the file and
// this test fails on the fields it can no longer decode. If a field is added,
// the strict decoder rejects it until the monitor learns the field too.
func TestWireContractDecode(t *testing.T) {
	data, err := os.ReadFile(wireContractPath)
	if err != nil {
		t.Fatalf("read %s: %v", wireContractPath, err)
	}
	var got wireContractPayload
	if err := decodeWireStrict(data, &got); err != nil {
		t.Fatalf("decode wire contract: %v", err)
	}

	want := wireContractPayload{
		Runs: []Run{{
			ID:        "run-contract-1",
			TaskID:    "T-CONTRACT",
			State:     "waiting_ci",
			PR:        42,
			HeadSHA:   "deadbeef",
			Branch:    "beacon/T-CONTRACT",
			Reason:    "checking CI",
			UpdatedAt: "2026-11-25T10:00:00Z",
		}},
		Event: Event{
			ID:    17,
			Type:  "idle",
			RunID: "run-contract-1",
			At:    "2026-11-25T10:00:00Z",
		},
		Control: ControlResult{
			OK:      true,
			RunID:   "run-contract-1",
			Action:  "approve",
			Applied: true,
		},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("wire contract decoded as %+v, want %+v", got, want)
	}
}

// TestWireEventPayloadFixtures pins the data lines of the ping and pr_changed
// frames. Each fixture uses the strict decoder, so a new key in a daemon event
// payload fails the test instead of being ignored.
func TestWireEventPayloadFixtures(t *testing.T) {
	t.Run("ping", func(t *testing.T) {
		var got wirePingPayload
		if err := decodeWireStrict([]byte(`{"time":"2026-11-25T10:00:00Z"}`), &got); err != nil {
			t.Fatalf("decode ping fixture: %v", err)
		}
		want := wirePingPayload{Time: "2026-11-25T10:00:00Z"}
		if got != want {
			t.Fatalf("ping fixture decoded as %+v, want %+v", got, want)
		}
	})

	t.Run("pr_changed", func(t *testing.T) {
		var got wirePRChangedPayload
		if err := decodeWireStrict([]byte(`{"pr":42}`), &got); err != nil {
			t.Fatalf("decode pr_changed fixture: %v", err)
		}
		want := wirePRChangedPayload{PR: 42}
		if got != want {
			t.Fatalf("pr_changed fixture decoded as %+v, want %+v", got, want)
		}
	})
}

// coreControlVerbs resolves core.ControlActions through the Control* constants
// declared beside it. The returned order is the wire order core publishes.
func coreControlVerbs(t *testing.T) []string {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), coreVocabularyPath, nil, 0)
	if err != nil {
		t.Fatalf("parser.ParseFile(%q): %v", coreVocabularyPath, err)
	}
	constants := map[string]string{}
	var verbs []string
	for _, decl := range f.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gen.Specs {
			values, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			switch gen.Tok {
			case token.CONST:
				for i, name := range values.Names {
					if i >= len(values.Values) {
						continue
					}
					lit, ok := values.Values[i].(*ast.BasicLit)
					if !ok || lit.Kind != token.STRING {
						continue
					}
					value, err := strconv.Unquote(lit.Value)
					if err != nil {
						t.Fatalf("%s: unquote %s: %v", coreVocabularyPath, lit.Value, err)
					}
					constants[name.Name] = value
				}
			case token.VAR:
				if len(values.Names) != 1 || values.Names[0].Name != "ControlActions" {
					continue
				}
				if len(values.Values) != 1 {
					t.Fatalf("%s: ControlActions has %d values", coreVocabularyPath, len(values.Values))
				}
				array, ok := values.Values[0].(*ast.CompositeLit)
				if !ok {
					t.Fatalf("%s: ControlActions is not a literal array", coreVocabularyPath)
				}
				for _, element := range array.Elts {
					id, ok := element.(*ast.Ident)
					if !ok {
						t.Fatalf("%s: ControlActions has a non-constant element", coreVocabularyPath)
					}
					verb, ok := constants[id.Name]
					if !ok {
						t.Fatalf("%s: action %s has no constant value", coreVocabularyPath, id.Name)
					}
					verbs = append(verbs, verb)
				}
			}
		}
	}
	if len(verbs) == 0 {
		t.Fatalf("%s: core vocabulary is empty", coreVocabularyPath)
	}
	return verbs
}

// TestControlVocabularyMatchesCore proves the TUI sends exactly the verbs core
// accepts. Adding a core action without a TUI action changes the expected list
// and fails this test.
func TestControlVocabularyMatchesCore(t *testing.T) {
	want := coreControlVerbs(t)
	got := make([]string, 0, len(actions))
	for _, action := range actions {
		got = append(got, string(action))
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("TUI actions = %v, core.ControlActions = %v", got, want)
	}
}
